def sequentialDigits(low, high):
    result = []
    digits = '123456789'

    min_len = len(str(low))
    max_len = len(str(high))

    for size in range(min_len, max_len + 1):
        for start in range(0, 10 - size):
            num = int(digits[start: start + size])
            if low <= num <= high:
                result.append(num)
    return result
